// Leaf node types
export type Quantifier = TSKindId.Star | TSKindId.Plus | TSKindId.Qmark;
export type Identifier = Terminal<TSKindId.Identifier, string>;
export type ImmediateIdentifier = Terminal<TSKindId.ImmediateIdentifier, string>;
export type PredicateType = TSKindId.Qmark | TSKindId.Bang;
export type StringContentText = Terminal<TSKindId.StringContentText, string>;
export type Anchor = TSKindId.Anchor;
export type Tight = TSKindId.Tight;
export type Space = TSKindId.Space;
export type Tab = TSKindId.Tab;
export type Newline = TSKindId.Newline;
export type Blankline = TSKindId.Blankline;
export type DoubleBlankline = TSKindId.DoubleBlankline;
export type Indent = TSKindId.Indent;
export type Dedent = TSKindId.Dedent;

// Supertype unions
export type Definition = NamedNode | AnonymousNode | MissingNode | Grouping | Predicate | List | FieldDefinition;

export type NamedNode = NamedNodePlain | NamedNodeSupertyped;

export type ListElement = Capture | ListElementQuantifier;

export type NamedNodeGroup = NamedNodeGroupChildren | NamedNodeGroupAnchoredLast;

export type Whitespace = Tight | Space | Tab | Newline | Blankline | DoubleBlankline | Indent | Dedent;

export namespace Definition {
	export type Kind = 'definition';
	export type Bound = SupertypeSurface<Definition, BoundByKindId>;
	export type Parsed = SupertypeSurface<Definition, ParsedByKindId>;
}

export namespace NamedNode {
	export type Kind = 'named_node';
	export type Bound = SupertypeSurface<NamedNode, BoundByKindId>;
	export type Parsed = SupertypeSurface<NamedNode, ParsedByKindId>;
}

export namespace ListElement {
	export type Kind = '_list_element';
	export type Bound = SupertypeSurface<ListElement, BoundByKindId>;
	export type Parsed = SupertypeSurface<ListElement, ParsedByKindId>;
}

export namespace NamedNodeGroup {
	export type Kind = 'named_node_group';
	export type Bound = SupertypeSurface<NamedNodeGroup, BoundByKindId>;
	export type Parsed = SupertypeSurface<NamedNodeGroup, ParsedByKindId>;
}

export namespace Whitespace {
	export type Kind = '_whitespace';
	export type Bound = SupertypeSurface<Whitespace, BoundByKindId>;
	export type Parsed = SupertypeSurface<Whitespace, ParsedByKindId>;
}

